-- +goose NO TRANSACTION
-- +goose Up
-- Destructive (ADR 0033, ADR 0071): a Tracking domain is the Workspace's own, not a Sending
-- domain's. The tracking columns of sending_domains are dropped and nothing moves to the new
-- tracking_domains table: there are no production Workspaces, and a host is set anew on the
-- Tracking settings page. So the edge tears down what it provisioned, every track.<domain> host
-- that was verified is logged as removed first, and the change log names a host instead of a
-- Sending domain. ent's diff wrote the table, the indexes and the column drops; the log rewrite
-- and the removals are written by hand, and an index on an existing table is created and dropped
-- concurrently (hence no transaction).
-- modify "tracking_host_changes" table: the host replaces the Sending domain it was derived from
ALTER TABLE "tracking_host_changes" ADD COLUMN "host" character varying NOT NULL DEFAULT '';
UPDATE "tracking_host_changes" SET "host" = 'track.' || "domain";
INSERT INTO "tracking_host_changes" ("workspace_id", "host", "state", "created_at", "updated_at")
SELECT "workspace_id", 'track.' || "domain", 'removed', now(), now()
FROM "sending_domains"
WHERE "tracking_state" IN ('dns_verified', 'serving') AND "discarded_at" IS NULL
ORDER BY "id";
ALTER TABLE "tracking_host_changes" ALTER COLUMN "host" DROP DEFAULT;
ALTER TABLE "tracking_host_changes" DROP COLUMN "domain";
-- create index "trackinghostchange_host" to table: "tracking_host_changes"
CREATE INDEX CONCURRENTLY "trackinghostchange_host" ON "tracking_host_changes" ("host");
-- drop index "sendingdomain_domain" from table: "sending_domains"
DROP INDEX CONCURRENTLY "sendingdomain_domain";
-- modify "sending_domains" table
ALTER TABLE "sending_domains" DROP CONSTRAINT "sending_domains_tracking_reason_check", DROP CONSTRAINT "sending_domains_tracking_state_check", DROP COLUMN "tracking_state", DROP COLUMN "tracking_checked_at", DROP COLUMN "tracking_reason", DROP COLUMN "tracking_state_changed_at";
-- create "tracking_domains" table
CREATE TABLE "tracking_domains" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "host" character varying NOT NULL, "role" character varying NOT NULL, "state" character varying NOT NULL DEFAULT 'pending', "served_at" timestamptz NULL, "checked_at" timestamptz NULL, "reason" character varying NULL, "state_changed_at" timestamptz NULL, "workspace_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "tracking_domains_workspaces_tracking_domains" FOREIGN KEY ("workspace_id") REFERENCES "workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "tracking_domains_reason_check" CHECK ((reason)::text = 'host_taken'::text), CONSTRAINT "tracking_domains_retired_check" CHECK (((role)::text <> 'retired'::text) OR ((state)::text = ANY ((ARRAY['dns_verified'::character varying, 'serving'::character varying])::text[]))), CONSTRAINT "tracking_domains_role_check" CHECK ((role)::text = ANY ((ARRAY['current'::character varying, 'replacement'::character varying, 'retired'::character varying])::text[])), CONSTRAINT "tracking_domains_state_check" CHECK ((state)::text = ANY ((ARRAY['pending'::character varying, 'dns_verified'::character varying, 'serving'::character varying])::text[])));
-- create index "trackingdomain_host" to table: "tracking_domains"
-- squawk-ignore require-concurrent-index-creation
CREATE UNIQUE INDEX "trackingdomain_host" ON "tracking_domains" ("host") WHERE (state IN ('dns_verified', 'serving'));
-- create index "trackingdomain_workspace_id_host" to table: "tracking_domains"
-- squawk-ignore require-concurrent-index-creation
CREATE UNIQUE INDEX "trackingdomain_workspace_id_host" ON "tracking_domains" ("workspace_id", "host");
-- create index "trackingdomain_workspace_id_role" to table: "tracking_domains"
-- squawk-ignore require-concurrent-index-creation
CREATE UNIQUE INDEX "trackingdomain_workspace_id_role" ON "tracking_domains" ("workspace_id", "role") WHERE (role IN ('current', 'replacement'));

-- +goose Down
-- reverse: create "tracking_domains" table (its indexes go with it)
DROP TABLE "tracking_domains";
