-- reverse: drop index "sendingdomain_domain" from table: "sending_domains"
CREATE UNIQUE INDEX CONCURRENTLY "sendingdomain_domain" ON "sending_domains" ("domain") WHERE (tracking_state IN ('dns_verified', 'serving') AND discarded_at IS NULL);
-- reverse: create index "trackinghostchange_host" to table: "tracking_host_changes"
DROP INDEX CONCURRENTLY "trackinghostchange_host";
-- reverse: modify "tracking_host_changes" table
ALTER TABLE "tracking_host_changes" ADD COLUMN "domain" character varying NOT NULL DEFAULT '';
UPDATE "tracking_host_changes" SET "domain" = substr("host", length('track.') + 1) WHERE "host" LIKE 'track.%';
